      "title": "ゲルマン人ってどんな人たちなんだろう？",
      "body": [
        "その後、ゲルマン人社会で農耕が発達して人口が増加すると、耕地不足となったゲルマン世界から、少しずつローマ領内に移住する人も現れた。ローマ帝国も外敵の侵入で兵力が足りなかったから、多数のゲルマン人を<span class=\"source-bold\">傭兵</span>として使ったり、大土地所有者のもとでコロヌスとなるゲルマン人も現れた。こんなふうに、帝政末期のローマには、多くのゲルマン人がコロヌスや傭兵として居住していたよ。ただ、あくまでも家族単位での引っ越しだから、民族移動とはいわない。もっと大規模に、民族ごとゴッソリ移動するのが「ゲルマン人の移動」だ！",
        "ローマの影響を受けたゲルマン人世界は、戦士中心の社会に変わってきたよ。ローマで傭兵となった人は、帰国後、「あの人は強い戦士だ［顔アイコン］」と人びとの尊敬を集めて軍団の指揮権を握り、ほかの軍団と抗争しながら権力を強めた。そして権力闘争を勝ち抜いた首長を中心に、ゲルマン人は10コくらいの大部族（シュタム）に統合された。4世紀後半に大移動を始めるのは、この大部族だよ。民族移動の内的な原因は耕地不足、直接のきっかけはフン人の西進だ。"
      ],
