      "title": "ローマ帝国における「皇帝権と教皇権の関係」を理解しよう！",
      "body": [
        "すると、ペテロの墓所（サン＝ピエトロ大聖堂は「聖ペテロ」の大聖堂だ）のあるローマが「イエスの弟子（使徒）の最高位だったペテロの後継者だから、ローマ教会のほうがエライ！」と首位権を主張して、ローマ司教が<span class=\"source-bold\">教皇</span>と称した。そして初代教皇<span class=\"source-bold\">レオ1世</span>は、カルケドン公会議で、東ローマ領内（エジプトやシリア）に多い<span class=\"source-bold\">単性論</span>を異端として、「私が東側の教会にも力を持っている！」と、教皇としての正統性を主張した。また西ローマ帝国滅亡の前だから、東ローマ皇帝も「やれやれ［顔アイコン］」と思ったんだけど、西ローマ帝国が滅亡すると状況が変わるよ。",
        "ローマ教会を保護していた西ローマ皇帝がいなくなり、皇帝は東ローマ皇帝だけになったから、コンスタンティノープル教会は「西ローマ帝国がなくなったんだから、こちらが上だ［顔アイコン］」と言い始めた。ローマ教皇は反論したかったけど、西側にはゲルマン人の国が乱立して、異端の<span class=\"source-bold\">アリウス派</span>が多い。仕方なく、ローマ教皇は東ローマ皇帝に保護を求めた［顔アイコン］。ただ、どちらも「自分のほうが上だ！」と思ってるから、東西教会の首位権をめぐる争いが激化したんだよ。"
      ],
