      "id": "c04-l11-p02-004",
      "title": "聖像禁止令をきっかけに、ローマ教皇とビザンツ帝国が激しく対立！",
      "body": [
        "こうなると、アリウス派が多いゲルマン人をアタナシウス派に改宗させるしかない！　このゲルマン人への布教に活躍したのが<span class=\"source-bold\">修道院</span>だよ。6世紀になると<span class=\"source-bold\">ベネディクトゥス</span>が中部イタリアの<span class=\"source-bold\">モンテ＝カシノ</span>に修道院をつくり、「祈り、働け」をモットーとする厳しい戒律（聖ベネディクトゥスの戒律）を課して、理想的な聖職者の生活を追い求めた。こうして西ヨーロッパ全体に広がった修道院運動を背景に、教皇<span class=\"source-bold\">グレゴリウス1世</span>は修道院を拠点にゲルマン人への布教を進め、ブリタニアのアングロ＝サクソン人や西ゴート人の改宗に成功したよ。ただ、布教のときに使っていた<span class=\"source-bold\">聖像</span>（イエスや聖者の絵や彫像）が、教皇とビザンツ【東ローマ】皇帝の対立を決定的にするんだ（7世紀以降の東ローマ帝国は一般に「ビザンツ帝国」と呼ぶよ（➡P.213）。"
      ],
