      "id": "c04-l11-p02-005",
      "title": "聖像禁止令をきっかけに、ローマ教皇とビザンツ帝国が激しく対立！",
      "body": [
        "東方からイスラーム勢力の圧迫を受けていたビザンツ皇帝<span class=\"source-bold\">レオン3世</span>は、偶像崇拝を厳格に禁止するイスラーム教徒に対抗して、726年、<span class=\"source-bold\">聖像禁止令</span>を出した。これは「イスラーム勢力に勝てなかったのは、ビザンツ帝国が聖像崇拝をしていたため」という意味で、本来はビザンツ帝国の法令だから西側には関係ないはずだった。でも、ローマ教皇はビザンツ皇帝に保護してもらってるでしょ。皇帝レオン3世は教皇に「キミが異端や異教徒にやられるのは、聖像なんかを使っているからですよ［顔アイコン］」とイヤミを言ってきた。これに対し、ゲルマン人への布教で聖像を使いたい教皇は「ビザンツ皇帝と手を切りたい［顔アイコン］」と思った。この聖像崇拝論争が激しくなると、ローマ教皇は、「ビザンツ皇帝に頼らないために、新たな教会の保護者としての“皇帝”をつくりたい！！」と、新たな政治権力との連携を探り始めたんだ。"
      ],
