      "id": "c04-l11-p02-006",
      "title": "アタナシウス派のフランク王国にローマ教皇が注目！",
      "body": [
        "教皇がいくら連携を探ったところで、アタナシウス派（正統派）の国としか組めない［顔アイコン］。ゲルマン人は、異端のアリウス派や古くからの自然崇拝をしている人が多かったから、連携は難しいよね。そこに登場したのが<span class=\"source-bold\">フランク王国</span>だよ。",
        "フランク人は、ローマの支配下にあったガリアに侵攻し、ライン川を越えてセーヌ川からロワール川の流域に南下すると、<span class=\"source-bold\">クローヴィス</span>がフランク諸部族を統合して、<span class=\"source-bold\">フランク王国</span>を建てた。クローヴィスの家系が<span class=\"source-bold\">メロヴィング朝</span>だよ。",
        "全フランクの王となったクローヴィスは、アタナシウス派の信者になっていた奥さんの勧めもあって、3000人もの兵士たちとともにアタナシウス派キリスト教に改宗した。これは、戦いで負けそうになっていたときに「神」に助けを求めたら逆転勝利したかららしいけど……ちと怪しい［顔アイコン］。",
        "まあ、そのあたりはともかく、<span class=\"source-bold\">クローヴィスの改宗</span>で旧ローマ系住民との宗教的な対立がなくなり、さらにアリウス派が多いゲルマン諸部族のなかでいち早く改宗したことで、ローマ末期から都市を支配していた司教たちと協力できるようになり、国内を支配しやすくなったんだ。"
      ],
