      "body": [
        "ただ、クローヴィスの死後、フランク王国は分裂・統合を繰り返した。メロヴィング家の後継者たちは抗争に明け暮れ、その結果、王権が弱体化する一方で、バラバラになっていたフランク王国のなかから<span class=\"source-bold\">カロリング家</span>が力を持ち始めた。カロリング家は、東部・西部・南部の3国に分かれたフランク王国のうち東部（アウストラシア）の有力な貴族で、宮廷ナンバー2の<span class=\"source-bold\">宮宰【マヨル＝ドムス】</span>の地位を独占していた家系だよ。そして、7世紀末にはカロリング家が中心になってフランク王国を統一して、「カロリング家のほうが強い！」という名声を得たんだ。"
      ],
