      "id": "c04-l11-p02-013",
      "title": "カールの戴冠によって中世西ヨーロッパ世界が誕生した！",
      "body": [
        "それじゃあ、カールの戴冠の意義を考えてみよう。政治的には、これまで西ヨーロッパに分立していたゲルマン人諸国がフランクによって統合され、ビザンツ帝国に匹敵する「<span class=\"source-bold\">西ローマ帝国が復活</span>」したことだ。「皇帝」は西欧を統一する支配者って意味だよ。宗教的には、フランク王国を保護者としたローマ教皇がビザンツ皇帝から自立して、西方キリスト教世界における教皇権の優位を示すことにもなった。これで、事実上東西教会が分裂（正式な分裂は1054年）したから、以後、西の教会を<span class=\"source-bold\">ローマ＝カトリック教会</span>、東の教会を<span class=\"source-bold\">ギリシア正教会</span>と呼ぶね。そして文化的には、「ゲルマン人」のカールが「キリスト教」の保護者として「ローマ」皇帝となり、カロリング＝ルネサンスなどを通じて、<span class=\"source-bold\">ローマ・ゲルマン・キリスト教文化</span>が融合した。こうして東西ヨーロッパ世界はそれぞれ独自の歴史を歩み始め、地中海世界は西ヨーロッパ・東ヨーロッパ（ビザンツ帝国）・イスラーム世界の三つに分かれた。つまり、カールの戴冠の意義を一言で言うと「<span class=\"source-bold\">中世西ヨーロッパ世界の誕生</span>」だね。"
      ],
      "plainBody": [
        "それじゃあ、カールの戴冠の意義を考えてみよう。政治的には、これまで西ヨーロッパに分立していたゲルマン人諸国がフランクによって統合され、ビザンツ帝国に匹敵する「西ローマ帝国が復活」したことだ。「皇帝」は西欧を統一する支配者って意味だよ。宗教的には、フランク王国を保護者としたローマ教皇がビザンツ皇帝から自立して、西方キリスト教世界における教皇権の優位を示すことにもなった。これで、事実上東西教会が分裂（正式な分裂は1054年）したから、以後、西の教会をローマ＝カトリック教会、東の教会をギリシア正教会と呼ぶね。そして文化的には、「ゲルマン人」のカールが「キリスト教」の保護者として「ローマ」皇帝となり、カロリング＝ルネサンスなどを通じて、ローマ・ゲルマン・キリスト教文化が融合した。こうして東西ヨーロッパ世界はそれぞれ独自の歴史を歩み始め、地中海世界は西ヨーロッパ・東ヨーロッパ（ビザンツ帝国）・イスラーム世界の三つに分かれた。つまり、カールの戴冠の意義を一言で言うと「中世西ヨーロッパ世界の誕生」だね。"
      ],
