      "id": "c04-l12-p01-003",
      "title": "ルーシの進出で、ロシアの起源となるキエフ公国ができた！",
      "body": [
        "それじゃあ、各地に進出したノルマン人の動きについて見ていこう！　ヴォルガ川やドニエプル川を通じた交易が盛んだったロシア方面には、スウェード人の一派<span class=\"source-bold\">ルーシ【ヴァリャーグ人】</span>が交易をしながら進出し、9世紀には首領の<span class=\"source-bold\">リューリク</span>が<span class=\"source-bold\">ノヴゴロド国</span>を建てたよ。部族対立が激しかった東スラヴ人が、抗争を終わらせるために統治者としてルーシを招いた、っていう言い伝えもあるけど、これは彼らがすでにロシア方面に拠点を築いていたってことだね［顔アイコン］。リューリクの兄弟も各地に進出して支配を拡大したから、彼らの部族名「ルーシ」が「ロシア」の語源になるんだ。そして、リューリク一族の<span class=\"source-bold\">オレーグ</span>はさらに南に遠征し、ドニエプル川中流に<span class=\"source-bold\">キエフ公国</span>を建てた。キエフはドニエプル川を通じたビザンツ帝国（東ローマ帝国）との交易拠点だったから、ノヴゴロドよりも交易の条件のよい土地を獲得した、ってことだね［顔アイコン］。",
        "その後、少数派だったルーシは先住民と同化してスラヴ化し、10世紀末には<span class=\"source-bold\">ウラディミル1世</span>がビザンツ帝国の援軍要請に応じたことから、ビザンツ皇帝バシレイオス2世の妹と結婚し、<span class=\"source-bold\">ギリシア正教</span>に改宗して国教にしたんだ。こうしてロシアでは、ビザンツ文化の影響を受けた独自の文化圏を形成するよ［顔アイコン］。"
      ],
      "plainBody": [
        "それじゃあ、各地に進出したノルマン人の動きについて見ていこう！　ヴォルガ川やドニエプル川を通じた交易が盛んだったロシア方面には、スウェード人の一派ルーシ【ヴァリャーグ人】が交易をしながら進出し、9世紀には首領のリューリクがノヴゴロド国を建てたよ。部族対立が激しかった東スラヴ人が、抗争を終わらせるために統治者としてルーシを招いた、っていう言い伝えもあるけど、これは彼らがすでにロシア方面に拠点を築いていたってことだね［顔アイコン］。リューリクの兄弟も各地に進出して支配を拡大したから、彼らの部族名「ルーシ」が「ロシア」の語源になるんだ。そして、リューリク一族のオレーグはさらに南に遠征し、ドニエプル川中流にキエフ公国を建てた。キエフはドニエプル川を通じたビザンツ帝国（東ローマ帝国）との交易拠点だったから、ノヴゴロドよりも交易の条件のよい土地を獲得した、ってことだね［顔アイコン］。",
        "その後、少数派だったルーシは先住民と同化してスラヴ化し、10世紀末にはウラディミル1世がビザンツ帝国の援軍要請に応じたことから、ビザンツ皇帝バシレイオス2世の妹と結婚し、ギリシア正教に改宗して国教にしたんだ。こうしてロシアでは、ビザンツ文化の影響を受けた独自の文化圏を形成するよ［顔アイコン］。"
      ],
