      "id": "c04-l12-p01-004",
      "title": "ノルマン人の進出で、複雑な英仏関係が形成された！",
      "body": [
        "<span class=\"source-bold\">西フランク王国（フランス）</span>にも9世紀後半からノルマン人が進出し、沿岸部だけではなく、セーヌ川を上ってパリなどの内陸の都市でも略奪をしていた。しかも、西フランクでは短命の王が続き、ノルマン人の進出に対処できなかった［顔アイコン］。ノルマン人は「今がチャンス！」とばかりに激しい略奪をおこない、しまいには河口付近に定住を始めたんだ。仕方なく、西フランク王<span class=\"source-bold\">シャルル3世</span>はノルマンの首領<span class=\"source-bold\">ロロ</span>に対して、カトリックの洗礼を受けることと引き換えにセーヌ川下流域の領有を認め、臣下として封じたよ。これが<span class=\"source-bold\">ノルマンディー公国</span>だ。これで略奪者はひとまず収まり、同じようにノルマン人（おもにデーン人）の進出していたイングランドとの交易や人材交流を盛んにおこなったんだ。"
      ],
      "plainBody": [
        "西フランク王国（フランス）にも9世紀後半からノルマン人が進出し、沿岸部だけではなく、セーヌ川を上ってパリなどの内陸の都市でも略奪をしていた。しかも、西フランクでは短命の王が続き、ノルマン人の進出に対処できなかった［顔アイコン］。ノルマン人は「今がチャンス！」とばかりに激しい略奪をおこない、しまいには河口付近に定住を始めたんだ。仕方なく、西フランク王シャルル3世はノルマンの首領ロロに対して、カトリックの洗礼を受けることと引き換えにセーヌ川下流域の領有を認め、臣下として封じたよ。これがノルマンディー公国だ。これで略奪者はひとまず収まり、同じようにノルマン人（おもにデーン人）の進出していたイングランドとの交易や人材交流を盛んにおこなったんだ。"
      ],
