        "西ヨーロッパの封建制は古代ゲルマン人の従士制と古代ローマの恩貸地制が結びついてできた、っていわれている。ゲルマンの従士制は、平民が貴族などの有力者に保護してもらうかわりに、従士として忠誠を誓うという制度だから、「個人と個人の契約」で結ばれた主従関係だね。ローマの恩貸地制は、土地所有者が自分の土地を守るために、有力者に土地をあげたことにして、改めて借り受ける制度だよ。場合によっては、主君が家臣に軍役などの奉仕を求めるかわりに、土地の使用権を貸し与えたりするから、こっちは「土地を与える」ことで結ばれる主従関係だ。この二つが結びつくと、主君が家臣（諸侯・騎士）に封土を与えるかわりに、家臣は主君に忠誠を誓って、軍役や貢納の義務を負うという主従関係ができた。これが封建的主従関係だ。"
