      "id": "c04-l12-p02-008",
      "title": "▼重量有輪犂",
      "body": [
        "ドイツ人はエルベ川を越えて<span class=\"source-bold\">東方植民</span>を進め、イベリア半島ではイスラーム教徒から土地を奪い返す<span class=\"source-bold\">レコンキスタ【国土回復運動／再征服運動】</span>が進み、さらに東地中海のイスラーム世界に直接攻め込む<span class=\"source-bold\">十字軍遠征</span>がおこなわれたのも、農業生産の増大と人口増加にともなう<span class=\"source-bold\">西ヨーロッパの拡大</span>だね。",
        "そして、農業生産が増えて余剰生産物が生まれると、荘園のなかに経済的な変化も生まれたんだ。中世の封建社会は荘園ごとの自給自足が基本で、各地を結ぶ交易は衰退していた。しかも荘園内部だけでちょこちょこと取引をしていたから、基本は物々交換（現物経済）だったんだ。でも、余剰生産物が生まれると、それを交換する商業が盛んになるよ。ここは次回、「<span class=\"source-bold\">商業ルネサンス</span>」のところで詳しく話すね。"
      ],
