      "title": "教皇と皇帝はどっちが上？　熾烈な叙任権闘争が起きた！",
      "body": [
        "しかし、世俗の権力からの「<span class=\"source-bold\">教会の自由</span>」を主張して改革を進める教皇<span class=\"source-bold\">グレゴリウス7世</span>は、「世俗の権力には司教を任命させない［顔アイコン］」と叙任権を教会が回収することを宣言し、皇帝による教会支配を攻撃した。これに対し、ドイツ王（のちの神聖ローマ皇帝）<span class=\"source-bold\">ハインリヒ4世</span>が教皇を廃位させようとしたんだけど、教皇グレゴ――教皇グレゴリウス7世は屈せずに王の<span class=\"source-bold\">破門（キリスト教世界からの追放を宣言すること）</span>を決議し「全キリスト教徒は、ハインリヒに仕えてはならない［顔アイコン］」と告げた。これを聞いて「チャンス！」と思ったのが、ドイツ王（皇帝）の統治に反抗的だった大諸侯たちだ。ドイツでは大諸侯の勢力が強く、彼らは「隙あらば国王（皇帝）の足を引っ張ってやる！」と思っていたから、「1年以内に破門を解かれなければ、ハインリヒを退位させる」と決議した。諸侯が反旗を翻したことで、ハインリヒ4世は教皇に謝罪して破門を解いてもらわないと、帝国の統治ができなくなった。こうしてハインリヒが北イタリアのカノッサ城の前で、しんしんと雪の降るなか裸足でひざまずき、涙を流して3日間も待ち続け、やっと破門を解いてもらったんだ。この事件が「<span class=\"source-bold\">カノッサの屈辱</span>」だよ。これで、ドイツ王権・皇帝権に対する<span class=\"source-bold\">教皇権の優位</span>が示されたことになるね。"
      ],
