      "id": "c04-l12-p03-008",
      "title": "インノケンティウス3世時代に、教皇権は絶頂になった！",
      "body": [
        "11世紀末に始まる<span class=\"source-bold\">十字軍遠征</span>で、西ヨーロッパでは宗教的な熱狂が起こり、それにつれて提唱者である教皇の権威も高まっていった。そして、西ヨーロッパ全体にカトリック教会の権威がおよぶようになると、12世紀末に登場した<span class=\"source-bold\">インノケンティウス3世</span>の時代に、教皇権は絶頂を迎えたんだ。彼は第4回ラテラノ公会議で、有名な「<span class=\"source-bold\">教皇は太陽であり、皇帝は月である</span>」との演説で教皇権を誇示し、各国の国王を次々と破門して優位に立った。この時期には、イギリス王<span class=\"source-bold\">ジョン</span>、フランス王<span class=\"source-bold\">フィリップ2世</span>、神聖ローマ皇帝<span class=\"source-bold\">オットー4世</span>など、主要国の君主はほとんど破門されているよ。また、<span class=\"source-bold\">托鉢修道会</span>を認可して民衆への教会の影響力を強めた。さらには「キリストの代理人」と主張して各国の紛争を仲裁するなど、実際の政治にまで介入したよ。ただ、こんな絶頂も長くは続かないからね［顔アイコン］。",
        "さて、今回はこれでおしまい。最後は年号チェックだ！",
        "次回は、いったん西ヨーロッパから離れてビザンツ帝国を中心とする東ヨーロッパ世界だよ。西ヨーロッパと比較して理解しよう［顔アイコン］。"
      ],
