        "死後、北イタリアにはランゴバルド人が侵入して国を建て、東方ではササン朝ペルシアとの抗争がますます激化した。さらにバルカン半島にはスラヴ人、アジア系遊牧民のブルガール人（トルコ系とされる）やアヴァール人まで侵入してきた。",
