      "title": "軍制の改革で帝国を復活させたヘラクレイオス1世",
      "body": [
        "もしユスティニアヌス帝の死後の皇帝が何もしなかったら、おそらくビザンツ帝国は滅んでいた［顔アイコン］。でも7世紀初め、<span class=\"source-bold\">ヘラクレイオス1世</span>はササン朝との戦争を再開し、一時はコンスタンティノープルを包囲されるなど危ない場面もあったけど持ちこたえて反撃し、ササン朝の都<span class=\"source-bold\">クテシフォン</span>に迫って降伏させた。さらに北から侵入したアヴァール人も撃退し、帝国の危機を救ったんだ。",
        "ただ、時代の流れには逆らえなかった。同じころムハンマドがイスラーム教を開くと、瞬く間にアラビア半島を統一し、続く正統カリフ時代にはビザンツ帝国から<span class=\"source-bold\">シリア・エジプト・メソポタミア</span>を奪った。軍事力を強化しないとイスラーム勢力を止められない。"
      ],
