        "8世紀に入ると、ビザンツ帝国は体制を立て直していった。有力な軍管区長官から皇帝になった<span class=\"source-bold\">レオン3世</span>は、各地の軍管区長官に自分の一族や信頼できる部下を任命して地方支配を強化し、中央政府の官僚機構も再編して皇帝専制体制をつくった。",
        "再びコンスタンティノープルを包囲したイスラーム勢力を撃退すると、皇帝が教会を管轄下に置いて宗教政策も主導した。具体的には、皇帝を「神の代理人」として、コンスタンティノープル総主教（東方教会のトップ）の任免権を皇帝が持つんだ。こういう体制を<span class=\"source-bold\">皇帝教皇主義</span>ともいうよ。"
