        "当時のビザンツ帝国では、宗教美術だといって教会が<span class=\"source-bold\">イコン（聖画像）</span>を崇拝していた。でも厳密に見れば、「旧約聖書」に書かれている偶像崇拝の禁止に違反しているよね。そこでレオン3世は、神が厳格に偶像崇拝を禁じるイスラーム教徒を使って帝国に罰を与えている、と考えた。",
        "そして、<span class=\"source-bold\">聖像禁止令［726］</span>を発布し、イエスや聖母マリアなどのイコン（聖画像）の制作や崇拝を禁止したんだ。東方教会ではもともと「立体の彫像はダメ！」とされていたから、イコンまで禁止すれば、すべての聖像崇拝を禁止したことになる。"
