      "id": "c04-l13-p02-003",
      "title": "レオン3世の聖像禁止令でローマ教会との対立が深まる！",
      "body": [
        "この決定がローマ教皇との対立を招いて、<span class=\"source-bold\">聖像崇拝論争</span>が起きた（第11回でも確認したよね）。ビザンツ帝国では100年以上にわたって<span class=\"source-bold\">イコノクラスム（聖像破壊運動）</span>が続き、聖像破壊派と聖像擁護派が激しく対立した。",
        "843年には聖像禁止令が解除され、イコン崇拝が復活した。だから、それ以後はむしろ<span class=\"source-bold\">聖像破壊のほうが異端</span>になるからね。",
        "ただ、聖像崇拝がOKになっても東西教会の対立は収まらなかった。聖像禁止令が廃止されたのはカール戴冠のあとだから、このころには事実上東西教会は分裂していた。そして、1054年の<span class=\"source-bold\">相互破門</span>によって正式に東西教会が分裂したんだ。"
      ],
