      "id": "c04-l13-p03-003",
      "title": "ビザンツ帝国は再び危機に！　もはや国境防衛の限界なのか？",
      "body": [
        "そうはいっても、もはや限界だよ［顔アイコン］。アレクシオス1世は仕方なく、<span class=\"source-bold\">教皇ウルバヌス2世</span>を通じて西ヨーロッパに援軍を要請した。相互破門までしたローマ教皇に援軍を頼むんだから、プライドも何もないよね。でも滅びる寸前だから、そんなこと言ってられない。この援軍要請が、西欧が<span class=\"source-bold\">十字軍遠征</span>を始めるきっかけになったんだ。",
        "ところが、とんでもない結果になる。",
        "ヴェネツィア商人が主導した<span class=\"source-bold\">第4回十字軍</span>は、なんとコンスタンティノープルを占領して<span class=\"source-bold\">ラテン帝国</span>を建ててしまった。ビザンツ帝国は対岸へ逃れて<span class=\"source-bold\">ニカイア帝国</span>を建て、その後ジェノヴァの協力を得てコンスタンティノープルを奪回したけど、もはや過去の栄光はない。思い出にひたるしかないよね。"
      ],
