      "body": [
        "もともとカルパティア山脈の北側からドニエプル川流域に住んでいた<span class=\"source-bold\">スラヴ人</span>は、6世紀ころに侵入したアヴァール人に圧迫され、東ヨーロッパ全域（ビザンツ帝国の北側）へ移動した。",
        "その後、東方から<span class=\"source-bold\">マジャール人</span>がドナウ川中流のパンノニアまで侵入すると、スラヴ人の居住地域は、マジャール人が建国した<span class=\"source-bold\">ハンガリー王国</span>を境に、ハンガリー北側が<span class=\"source-bold\">西スラヴ人</span>、南側が<span class=\"source-bold\">南スラヴ人</span>に分断された。そして、マジャール人が通過していったロシア方面には<span class=\"source-bold\">東スラヴ人</span>が定住した。"
      ],
