        "そして、14世紀半ばに即位した<span class=\"source-bold\">カール4世</span>は、その後、神聖ローマ皇帝に選ばれたんだ（カール4世）。こうしてベーメン、特にプラハは神聖ローマ帝国の中心として栄え、東欧最古の<span class=\"source-bold\">プラハ大学</span>が創設され、プラハ司教は大司教座に昇格した。さらに王権を強化したカール4世は、七選帝侯による皇帝選出を定めた<span class=\"source-bold\">金印勅書</span>を発布し、さらにアヴィニョンの教皇をローマへ帰還させたんだよ。"
