      "id": "c04-l14-p01-004",
      "title": "第1回十字軍で聖地を奪還！　でも、イスラーム教徒に奪い返された……",
      "body": [
        "それじゃあ、遠征の経過を見ていこう。<span class=\"source-bold\">第1回十字軍</span>は「聖地巡礼を中心とする軍隊遠征」だから、巡礼のためについてきた民衆もあわせて総勢10万人以上！　ただ、騎士は数千人で、歩兵を入れても兵士は全体の4分の1くらいだった。しかも、西欧各国の国王が破門されていて参加できなかった［顔アイコン］。だから、遠征軍の中心はフランスやイタリアの有力諸侯だよ。",
        "遠征軍は、まずコンスタンティノープルに集合したあと、陸路でシリアの主要都市を占領し、1099年には<span class=\"source-bold\">イェルサレム</span>を奪還。イスラーム教徒を大虐殺すると、現地に<span class=\"source-bold\">イェルサレム王国</span>などの十字軍国家を建国した。ただ、イェルサレムはイスラーム教の聖地でもあるから、イスラーム側だって「ぜったい取り返す！」って思うよね。これに対してキリスト教徒側は、聖地にとどまって巡礼者の保護や聖地の防衛をおこなう<span class=\"source-bold\">宗教騎士団</span>がつくられた。この時期につくられたのは、<span class=\"source-bold\">テンプル騎士団</span>と<span class=\"source-bold\">ヨハネ騎士団</span>だね。"
      ],
