      "id": "c04-l14-p01-006",
      "title": "第3回十字軍は、十字軍史上最大の遠征！　果たして結果は……？",
      "body": [
        "12世紀後半、イスラーム側の反撃が始まった！　エジプトに<span class=\"source-bold\">アイユーブ朝</span>を建てた<span class=\"source-bold\">サラーフ＝アッディーン【サラディン】</span>がシリアに進出し、聖地イェルサレムを奪還した。西欧もこれに対抗し、イングランド王<span class=\"source-bold\">リチャード1世（獅子心王）</span>、フランス王<span class=\"source-bold\">フィリップ2世（尊厳王）</span>、神聖ローマ皇帝<span class=\"source-bold\">フリードリヒ1世（バルバロッサ）</span>が参加する十字軍史上最大の遠征、<span class=\"source-bold\">第3回十字軍</span>がおこなわれたんだ。",
        "ただ、この十字軍もどうも上手くいかない［顔アイコン］。だいたい、英仏は領土などの問題でむちゃくちゃ仲が悪い！　だから、フランス王フィリップ2世は、アッコンを奪還すると「十字軍などやってる場合じゃない！」とさっさと帰国し、イングランドとの戦争に備えた。しかも、フリードリヒ1世は<span class=\"source-bold\">不慮の事故死</span>……。川を渡る途中で、甲冑（鎧）を着たまま川に落ちて溺れ死んだらしいよ［顔アイコン］。これでドイツも遠征から脱落したから、サラーフ＝アッディーンと戦ったのはイングランド王リチャード1世だけ。でも、彼の留守中に弟のジョンが本国で反乱［顔アイコン］。「このダメ弟め［顔アイコン］」と怒ったところで、帰国するしかない……。結局、リチャード1世も講和して帰国したから、第3回十字軍も失敗だ。",
        "ちなみに、この遠征の途中で<span class=\"source-bold\">ドイツ騎士団</span>が結成されているね。現地では大した活躍はしてないけど、十字軍が終わると東方植民で活躍するからね！"
      ],
