      "id": "c04-l14-p01-009",
      "title": "十字軍は、その後も失敗が続いて……目的を達成できないまま終結",
      "body": [
        "こうなると黙ってられなくなったのが、敬虔すぎるキリスト教徒で<span class=\"source-bold\">聖王</span>と呼ばれたフランス王<span class=\"source-bold\">ルイ9世</span>だ。彼は<span class=\"source-bold\">第6回十字軍</span>を起こして海路でエジプトを攻撃したけど、現地で遠征軍に疫病が流行って、降伏するしかなくなった。そこでルイ9世は、イスラーム勢力を挟み撃ちするために、東方で台頭するモンゴルとの提携を狙って、<span class=\"source-bold\">ルブルック</span>をカラコルムに派遣したけど、まんまと断られた。いきなりそんなことを頼んでも無理だよ……［顔アイコン］。その後ルイ9世は、再び<span class=\"source-bold\">第7回十字軍</span>を起こして海路でチュニスを攻撃したけど、本人が病死して遠征軍も壊滅した［顔アイコン］。",
        "これ以後、大規模な遠征がおこなわれることもなく、1291年には十字軍の拠点だった<span class=\"source-bold\">アッコン【アッコ】</span>が陥落して、約200年にわたる十字軍遠征は終わったんだ。"
      ],
