      "id": "c04-l14-p02-002",
      "title": "都市の市民たちは自治権を獲得！　都市内部ではギルドがつくられた",
      "body": [
        "ここから同じ西ヨーロッパにあった都市の多くは、もともとローマ時代に建設されたものや、司教座教会や君主の城などを中心にしたものが多かった。一方、中世にできた新都市は商業都市だよ。10世紀ごろから農業生産が増えると、余った穀物（<span class=\"source-bold\">余剰生産物</span>）などを交換するため、各地で市が開かれた。最初は日にちが決まっていない不定期市だったけど、その後、決まった日に商人や手工業者が集まる<span class=\"source-bold\">定期市</span>になっていった。ほら、今でも「♪20日、30日5％off〜♪」みたいなのがあるよね。決まった日に集まったほうが取引はスムーズだもんね。",
        "そして、定期市の場所に商人や手工業者が集まって住む<span class=\"source-bold\">中世都市</span>に発展し、11世紀ごろから人口も増え始めた。さらに十字軍をきっかけに遠隔地商業が発達すると、都市もますます発展したんだ。"
      ],
