      "id": "c04-l14-p02-004",
      "title": "都市の市民たちは自治権を獲得！　都市内部ではギルドがつくられた",
      "body": [
        "都市は周囲を壁（市壁）に囲まれていて、独自の都市法を制定するなど、周辺の農村とは一線を引いた共同体意識を持っていたんだ。また、12〜13世紀ごろのドイツでは、諸侯たちが大商人を集めて都市を建設させることも多かった。こうした都市は、「自治権をあげるから、都市を建設しなさい！」といって商人を集めたから、最初から大幅な自治権が認められていたよ。",
        "続いて、都市の内部の状況を見ていくよ。都市の政治は<span class=\"source-bold\">参事会</span>が管理していて、最初は大商人たちが市政を独占していた。大商人たちは排他的な<span class=\"source-bold\">商人ギルド</span>をつくって、加盟していない商人を取引に参入させなかった。だって、同じ種類の店がたくさんあると、1軒あたりの利益は減るでしょ［顔アイコン］。そして、商人ギルドに参加している大商人が参事会の運営を独占したんだよ。",
        "これに対して手工業の親方たちは「オマエたちだけで、勝手に決めるな［顔アイコン］」と怒って、商人ギルドに対抗して<span class=\"source-bold\">同職ギルド【ツンフト】</span>を結成した。そして、商人に対する<span class=\"source-bold\">ツンフト闘争</span>を経て、14世紀ごろには市政に参加するようになったんだ。"
      ],
