      "title": "領主が逆襲する封建反動に対して、農民一揆が起こった！",
      "body": [
        "同じように百年戦争の戦費に困ったイングランドでも、人頭税をかけたことをきっかけに<span class=\"source-bold\">ワット＝タイラーの乱</span>が起きた。ワット＝タイラーは指導者の名前だよ。この反乱にはロンドン市民や、「<span class=\"source-bold\">アダムが耕しイヴが紡いだとき、だれが貴族であったか</span>」と演説したことで有名な<span class=\"source-bold\">ジョン＝ボール</span>らも合流して大反乱になった。困った国王は農民たちの要求で、農奴制の廃止などを受け入れる、って約束したんだけど、最後はタイラーがダマされて殺され、鎮圧されちゃった［顔アイコン］。",
        "でも、イングランドではその後も各地で反乱が続き、結果的にはヨーマンが急増することになるよ。"
      ],
