      "id": "c04-l14-p03-006",
      "title": "領主が逆襲する封建反動に対して、農民一揆が起こった！",
      "body": [
        "反対にドイツでは、封建反動が成功して<span class=\"source-bold\">農奴制が再編され（再版農奴制）</span>、領主たちは農奴労働を強化した大土地経営を維持したんだ。こうした大農場では、16世紀以降、西欧向けの輸出用穀物がつくられた。これが<span class=\"source-bold\">グーツヘルシャフト</span>だよ。",
        "さらに、同じ時期のヨーロッパでは<span class=\"source-bold\">騎士が不要</span>になった。14世紀ごろから火器（大砲や鉄砲）の使用が始まって戦術が変化すると、戦いは歩兵による鉄砲隊が中心になった。こうなると甲冑を着て馬に乗る騎士は時代遅れだね。しかも鉄砲は日々訓練しなきゃいけないから、兵士は<span class=\"source-bold\">傭兵</span>が中心になる。騎士たちは、新たな道に進むしかないね……［顔アイコン］。有力な諸侯たちは宮廷貴族として国王の取り巻きになったけど、地方の弱小貴族は宮廷の下級官僚になったり、もはやただの地主になった。こうして形成された平民の地主階級を、イングランドでは<span class=\"source-bold\">ジェントリ</span>と呼んだ。"
      ],
      "plainBody": [
        "反対にドイツでは、封建反動が成功して農奴制が再編され（再版農奴制）、領主たちは農奴労働を強化した大土地経営を維持したんだ。こうした大農場では、16世紀以降、西欧向けの輸出用穀物がつくられた。これがグーツヘルシャフトだよ。",
        "さらに、同じ時期のヨーロッパでは騎士が不要になった。14世紀ごろから火器（大砲や鉄砲）の使用が始まって戦術が変化すると、戦いは歩兵による鉄砲隊が中心になった。こうなると甲冑を着て馬に乗る騎士は時代遅れだね。しかも鉄砲は日々訓練しなきゃいけないから、兵士は傭兵が中心になる。騎士たちは、新たな道に進むしかないね……［顔アイコン］。有力な諸侯たちは宮廷貴族として国王の取り巻きになったけど、地方の弱小貴族は宮廷の下級官僚になったり、もはやただの地主になった。こうして形成された平民の地主階級を、イングランドではジェントリと呼んだ。"
      ],
