      "id": "c04-l14-p03-007",
      "title": "王権強化が進んで教皇が屈服！　教皇権は大きく動揺した",
      "body": [
        "続いて教皇の話にいこう！　十字軍遠征の影響で王権強化が進み、ついに王権が優位に立つときがやってきた！　イングランドとの戦争にお金が必要になったフランス王<span class=\"source-bold\">フィリップ4世</span>は、新たな財源として<span class=\"source-bold\">聖職者に課税</span>することにした。この政策は間違いなく教皇との対立を引き起こすけど、すでにフランスは王権強化に成功している。強気のフィリップ4世は「破門されても、諸侯の反乱さえ起きなければ問題ない！」と考えて、聖職者・貴族・平民からなる<span class=\"source-bold\">全国三部会（三部会）</span>を招集すると、「オレ様が教皇に破門されても、教皇に味方するんじゃないぞ［顔アイコン］」と支持を確認したうえで、部下に命じてローマ近郊のアナーニで教皇<span class=\"source-bold\">ボニファティウス8世</span>を襲い、幽閉させた。このとき、教皇は顔面を殴打され、その後発狂して憤死した［顔アイコン］。この<span class=\"source-bold\">アナーニ事件</span>は、教皇権が没落して王権の優位が明らかになった事件だね。"
      ],
