      "title": "キリスト教の発展にともなって、教会建築も発達した！",
      "body": [
        "その後、12世紀に入ると建築技術の発達で、教会の建て方が変わるよ！　柱を先に組み、あとの壁や天井をはめる技術で尖頭アーチや高い天井をつくり、壁を薄くしたり窓を大きくしたりできるようになった。大きな窓は<span class=\"source-bold\">ステンドグラス</span>で飾り、光で神の世界を表現したんだよ。これが<span class=\"source-bold\">ゴシック様式</span>だ。",
        "フランスの<span class=\"source-bold\">サン＝ドニ修道院</span>に始まり、その後の西ヨーロッパの教会は、ほとんどゴシック様式で建てられた。フランスの<span class=\"source-bold\">ノートルダム大聖堂（パリ）</span>や<span class=\"source-bold\">シャルトル大聖堂</span>、イングランドの<span class=\"source-bold\">カンタベリ大聖堂</span>、ドイツの<span class=\"source-bold\">ケルン大聖堂</span>などが代表だね。"
      ],
