      "id": "c04-l15-p01-001",
      "title": "王権の強いイングランドと弱いフランス……ノルマン征服後の英仏関係は？",
      "body": [
        "それじゃあ、まずはイングランド（イギリス）とフランスから始めよう！",
        "第12回で話したように、イングランドの<span class=\"source-bold\">ノルマン朝</span>は、<span class=\"source-bold\">ウィリアム1世</span>がイングランドを征服してできたから、最初から王権が強かった。これは、ノルマン朝が本拠地のフランス側に領地を持っていることが背景だ。しかも、ノルマン朝が断絶したあとにイングランド王位を継承した<span class=\"source-bold\">ヘンリ2世（アンジュー伯アンリ）</span>は、父からアンジュー伯領を、母からノルマンディー公領を継承した。こうしてできた<span class=\"source-bold\">プランタジネット朝</span>は、イングランドに加えてフランスの西半分を領有する大勢力になった！　このため、イングランドVS.フランスは「1：1」じゃなくて「1.5：0.5」だよ［顔アイコン］。こうして、イングランドの王権はさらに強くなったけど、英王の大陸側の領地（在仏領）をめぐってフランス王と対立するよね。"
      ],
