      "id": "c04-l15-p02-005",
      "title": "敗れたイングランドでは、王位継承争いに乗じてバラ戦争が起こった！",
      "body": [
        "百年戦争中のイングランドでは、エドワード3世の息子の家系にあたる<span class=\"source-bold\">ランカスター朝</span>が王位を継いでいたけど、百年戦争終結の直後に、国王<span class=\"source-bold\">ヘンリ6世</span>が発狂して、政治ができなくなった［顔アイコン］。すると、同じくエドワード3世の息子の家系にあたる<span class=\"source-bold\">ヨーク家</span>と、これを支持する貴族たちは、ヨーク家を国王にして政治の主導権を握ろうとしたから、ランカスター家とヨーク家の王位継承争いが起きたんだ。",
        "このとき、イングランド国内の大貴族たちは「百年戦争で負けて損した分を、国内で対立している貴族を倒して取り返そう［顔アイコン］」と考えて、ランカスター派とヨーク派に分かれて内乱を始めた。これが<span class=\"source-bold\">バラ戦争</span>だよ。この名前は、両家の紋章が赤バラ（ランカスター家）と白バラ（ヨーク家）だったという伝承から19世紀についたんだけど、そんなことより大事なのは「<span class=\"source-bold\">バラ戦争で貴族が自滅した</span>」ことだよ！"
      ],
      "plainBody": [
        "百年戦争中のイングランドでは、エドワード3世の息子の家系にあたるランカスター朝が王位を継いでいたけど、百年戦争終結の直後に、国王ヘンリ6世が発狂して、政治ができなくなった［顔アイコン］。すると、同じくエドワード3世の息子の家系にあたるヨーク家と、これを支持する貴族たちは、ヨーク家を国王にして政治の主導権を握ろうとしたから、ランカスター家とヨーク家の王位継承争いが起きたんだ。",
        "このとき、イングランド国内の大貴族たちは「百年戦争で負けて損した分を、国内で対立している貴族を倒して取り返そう［顔アイコン］」と考えて、ランカスター派とヨーク派に分かれて内乱を始めた。これがバラ戦争だよ。この名前は、両家の紋章が赤バラ（ランカスター家）と白バラ（ヨーク家）だったという伝承から19世紀についたんだけど、そんなことより大事なのは「バラ戦争で貴族が自滅した」ことだよ！"
      ],
