      "id": "c04-l15-p02-006",
      "title": "敗れたイングランドでは、王位継承争いに乗じてバラ戦争が起こった！",
      "body": [
        "そもそも貴族たちは、自分の勢力を拡大したいだけ［顔アイコン］。最初はヨーク派の貴族ら、<span class=\"source-bold\">エドワード4世</span>が即位して<span class=\"source-bold\">ヨーク朝</span>ができたけど、ランカスター派も「オマエら、絶対ぶっ潰す［顔アイコン］」と反撃した。こうして貴族たちが潰し合うなかで、内乱を勝ち抜いたランカスター系の<span class=\"source-bold\">ヘンリ＝テューダー</span>が国王となり（<span class=\"source-bold\">ヘンリ7世</span>）、ヨーク家の娘と結婚して王家を統合すると、「もう対立する理由はない。王家は一つだ！」として内乱を収めた。これが<span class=\"source-bold\">テューダー朝</span>の成立だよ。",
        "ヘンリ7世は没収した領地を王領地として財政を強化すると、国王評議会に特別法廷をつくって（のちにヘンリ8世が<span class=\"source-bold\">星室庁裁判所</span>として整備）、反対派を抑えた。こうして大貴族勢力が潰れて王権が強まったよ［顔アイコン］。"
      ],
      "plainBody": [
        "そもそも貴族たちは、自分の勢力を拡大したいだけ［顔アイコン］。最初はヨーク派の貴族ら、エドワード4世が即位してヨーク朝ができたけど、ランカスター派も「オマエら、絶対ぶっ潰す［顔アイコン］」と反撃した。こうして貴族たちが潰し合うなかで、内乱を勝ち抜いたランカスター系のヘンリ＝テューダーが国王となり（ヘンリ7世）、ヨーク家の娘と結婚して王家を統合すると、「もう対立する理由はない。王家は一つだ！」として内乱を収めた。これがテューダー朝の成立だよ。",
        "ヘンリ7世は没収した領地を王領地として財政を強化すると、国王評議会に特別法廷をつくって（のちにヘンリ8世が星室庁裁判所として整備）、反対派を抑えた。こうして大貴族勢力が潰れて王権が強まったよ［顔アイコン］。"
      ],
