      "id": "c04-l15-p03-002",
      "title": "神聖ローマ皇帝は、イタリア政策ばかりでドイツも統一できず！",
      "body": [
        "その後、フリードリヒ1世の孫にあたる<span class=\"source-bold\">フリードリヒ2世</span>は、母親がシチリア国王の娘だったから、幼いころからシチリアで育ち、皇帝になったのちもほとんどシチリア島にいた。彼の時代にドイツの教会（聖界諸侯）や諸侯・都市は特権を認められて自立し、ドイツの分裂はさらに深まった。しかも、フリードリヒ2世が第5回十字軍で教皇と対立すると、こともあろうか長男が反逆［顔アイコン］。仕方なく息子を処刑して死に追いやった。シュタウフェン朝は、もはや神に見放されたのか［顔アイコン］？"
      ],
