      "title": "ドイツに皇帝がいない？　大空位時代、そして金印勅書を発布！",
      "body": [
        "その後、1356年にルクセンブルク朝の神聖ローマ皇帝<span class=\"source-bold\">カール4世</span>が<span class=\"source-bold\">金印勅書【黄金文書】</span>を発布して、皇帝選出権を7人の<span class=\"source-bold\">選帝侯</span>（マインツ・トリーア・ケルン大司教、ファルツ伯、ザクセン公、ブランデンブルク辺境伯、ベーメン王の7人）に与えて、その多数決で決まったドイツ王が教皇の認可なしで皇帝となることを認めたんだ。一方で、選帝侯にはさまざまな特権が認められて<span class=\"source-bold\">領邦君主</span>になった。だからこのあと、ほぼ独立国になった選帝侯や大幅な特権を認められた諸侯の<span class=\"source-bold\">領邦</span>が、それぞれの領内で独自に中央集権化を進めることになるよ。そして、1438年から<span class=\"source-bold\">ハプスブルク家</span>が帝位を世襲するんだけど、ハプスブルク家も自分の領地の支配を優先したから、ドイツは統一が進まないんだね。"
      ],
      "plainBody": [
        "その後、1356年にルクセンブルク朝の神聖ローマ皇帝カール4世が金印勅書【黄金文書】を発布して、皇帝選出権を7人の選帝侯（マインツ・トリーア・ケルン大司教、ファルツ伯、ザクセン公、ブランデンブルク辺境伯、ベーメン王の7人）に与えて、その多数決で決まったドイツ王が教皇の認可なしで皇帝となることを認めたんだ。一方で、選帝侯にはさまざまな特権が認められて領邦君主になった。だからこのあと、ほぼ独立国になった選帝侯や大幅な特権を認められた諸侯の領邦が、それぞれの領内で独自に中央集権化を進めることになるよ。そして、1438年からハプスブルク家が帝位を世襲するんだけど、ハプスブルク家も自分の領地の支配を優先したから、ドイツは統一が進まないんだね。"
      ],
