      "id": "c04-l15-p04-001",
      "title": "イスラーム教徒が征服したイベリア半島で、レコンキスタが始まる！",
      "body": [
        "711年、北アフリカから侵入したイスラーム勢力（<span class=\"source-bold\">ウマイヤ朝</span>）が<span class=\"source-bold\">西ゴート王国</span>を滅ぼした後、イベリア半島はイスラーム教徒の支配下に入った。以後、半島の北部のキリスト教徒は、すでに8世紀から約800年にわたってイスラーム教徒に取られた領土を取り返す<span class=\"source-bold\">レコンキスタ【国土回復運動／再征服運動】</span>を進めるよ。10世紀ごろに<span class=\"source-bold\">レオン王国、ナバラ王国</span>などのキリスト教諸国がイスラーム勢力と戦ったけど、南部で<span class=\"source-bold\">ウマイヤ朝やムラービト朝</span>が強かったから、あまり進まなかったんだ。"
      ],
      "plainBody": [
        "711年、北アフリカから侵入したイスラーム勢力（ウマイヤ朝）が西ゴート王国を滅ぼした後、イベリア半島はイスラーム教徒の支配下に入った。以後、半島の北部のキリスト教徒は、すでに8世紀から約800年にわたってイスラーム教徒に取られた領土を取り返すレコンキスタ【国土回復運動／再征服運動】を進めるよ。10世紀ごろにレオン王国、ナバラ王国などのキリスト教諸国がイスラーム勢力と戦ったけど、南部でウマイヤ朝やムラービト朝が強かったから、あまり進まなかったんだ。"
      ],
